-- Extend only the verified deployed financial row shapes. Existing prefixes,
-- formulas and records stay intact; canonical names use their own source bases.
-- Recorded contract is never aliased from adjusted/authorized contract.
do $bridge$ declare shape jsonb;definition text;begin
if to_regclass('public.invoice_financial_summary') is not null and not exists(select 1 from pg_attribute where attrelid='public.invoice_financial_summary'::regclass and attname='tax_amount' and attnum>0 and not attisdropped) then
 select jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod)) order by attnum) into shape from pg_attribute where attrelid='public.invoice_financial_summary'::regclass and attnum>0 and not attisdropped;
 if shape is distinct from $shape$[{"name":"invoice_id","type":"uuid"},{"name":"company_id","type":"uuid"},{"name":"project_id","type":"uuid"},{"name":"customer_id","type":"uuid"},{"name":"invoice_number","type":"text"},{"name":"invoice_type","type":"text"},{"name":"status","type":"text"},{"name":"issue_date","type":"date"},{"name":"due_date","type":"date"},{"name":"billing_period_start","type":"date"},{"name":"billing_period_end","type":"date"},{"name":"po_number","type":"text"},{"name":"bill_to_name","type":"text"},{"name":"bill_to_contact","type":"text"},{"name":"bill_to_email","type":"text"},{"name":"sales_tax_rate_percent","type":"numeric(8,5)"},{"name":"sales_tax_exempt","type":"boolean"},{"name":"sales_tax_jurisdiction","type":"text"},{"name":"retainage_percent","type":"numeric(6,3)"},{"name":"terms_text","type":"text"},{"name":"notes","type":"text"},{"name":"sent_at","type":"timestamp with time zone"},{"name":"voided_at","type":"timestamp with time zone"},{"name":"subtotal","type":"numeric"},{"name":"taxable_subtotal","type":"numeric"},{"name":"sales_tax","type":"numeric"},{"name":"retainage_held","type":"numeric"},{"name":"invoice_total","type":"numeric"},{"name":"amount_paid","type":"numeric"},{"name":"balance_due","type":"numeric"},{"name":"collection_status","type":"text"},{"name":"days_overdue","type":"integer"},{"name":"aging_bucket","type":"text"}]$shape$::jsonb then raise exception 'Unrecognized deployed invoice_financial_summary row shape: %',shape;end if;
 definition:=pg_get_viewdef('public.invoice_financial_summary'::regclass,true);execute 'create view public.carez_invoice_prefix_bridge with(security_invoker=true) as '||definition;
 execute $ddl$create or replace view public.invoice_financial_summary with(security_invoker=true) as select v.*,v.sales_tax::numeric tax_amount,i.created_at,i.updated_at from public.carez_invoice_prefix_bridge v join public.invoices i on i.company_id=v.company_id and i.id=v.invoice_id$ddl$;
 revoke all on public.carez_invoice_prefix_bridge,public.invoice_financial_summary from public,anon,authenticated;grant select on public.carez_invoice_prefix_bridge,public.invoice_financial_summary to authenticated;
end if;
if to_regclass('public.payment_financial_summary') is not null and not exists(select 1 from pg_attribute where attrelid='public.payment_financial_summary'::regclass and attname='unallocated_amount' and attnum>0 and not attisdropped) then
 select jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod)) order by attnum) into shape from pg_attribute where attrelid='public.payment_financial_summary'::regclass and attnum>0 and not attisdropped;
 if shape is distinct from $shape$[{"name":"payment_id","type":"uuid"},{"name":"company_id","type":"uuid"},{"name":"customer_id","type":"uuid"},{"name":"project_id","type":"uuid"},{"name":"received_date","type":"date"},{"name":"amount","type":"numeric(14,2)"},{"name":"processing_fee","type":"numeric(14,2)"},{"name":"payment_method","type":"text"},{"name":"reference_number","type":"text"},{"name":"notes","type":"text"},{"name":"status","type":"text"},{"name":"allocated_amount","type":"numeric"},{"name":"unapplied_amount","type":"numeric"}]$shape$::jsonb then raise exception 'Unrecognized deployed payment_financial_summary row shape: %',shape;end if;
 definition:=pg_get_viewdef('public.payment_financial_summary'::regclass,true);execute 'create view public.carez_payment_prefix_bridge with(security_invoker=true) as '||definition;
 execute $ddl$create or replace view public.payment_financial_summary with(security_invoker=true) as select v.*,(p.amount-coalesce((select sum(a.amount) from public.payment_allocations a where a.company_id=p.company_id and a.payment_id=p.id),0))::numeric unallocated_amount,p.created_at from public.carez_payment_prefix_bridge v join public.customer_payments p on p.company_id=v.company_id and p.id=v.payment_id$ddl$;
 revoke all on public.carez_payment_prefix_bridge,public.payment_financial_summary from public,anon,authenticated;grant select on public.carez_payment_prefix_bridge,public.payment_financial_summary to authenticated;
end if;
if to_regclass('public.project_commitment_summary') is not null and not exists(select 1 from pg_attribute where attrelid='public.project_commitment_summary'::regclass and attname='commitment_status' and attnum>0 and not attisdropped) then
 select jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod)) order by attnum) into shape from pg_attribute where attrelid='public.project_commitment_summary'::regclass and attnum>0 and not attisdropped;
 if shape is distinct from $shape$[{"name":"project_id","type":"uuid"},{"name":"company_id","type":"uuid"},{"name":"job_number","type":"text"},{"name":"name","type":"text"},{"name":"issued_po_total","type":"numeric"},{"name":"po_actual_cost","type":"numeric"},{"name":"open_po_commitments","type":"numeric"},{"name":"open_po_count","type":"integer"}]$shape$::jsonb then raise exception 'Unrecognized deployed project_commitment_summary row shape: %',shape;end if;
 definition:=pg_get_viewdef('public.project_commitment_summary'::regclass,true);execute 'create view public.carez_commitment_prefix_bridge with(security_invoker=true) as '||definition;
 execute $ddl$create or replace view public.project_commitment_summary with(security_invoker=true) as select v.*,case when exists(select 1 from public.purchase_order_financial_summary s where s.company_id=v.company_id and s.project_id=v.project_id and s.status='issued' and (s.open_commitment is null or s.open_commitment::text in ('NaN','Infinity','-Infinity'))) then 'unavailable' else 'known' end commitment_status from public.carez_commitment_prefix_bridge v$ddl$;
 revoke all on public.carez_commitment_prefix_bridge,public.project_commitment_summary from public,anon,authenticated;grant select on public.carez_commitment_prefix_bridge,public.project_commitment_summary to authenticated;
end if;
if to_regclass('public.project_billing_summary') is not null and not exists(select 1 from pg_attribute where attrelid='public.project_billing_summary'::regclass and attname='original_contract_value' and attnum>0 and not attisdropped) then
 select jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod)) order by attnum) into shape from pg_attribute where attrelid='public.project_billing_summary'::regclass and attnum>0 and not attisdropped;
 if shape is distinct from $shape$[{"name":"project_id","type":"uuid"},{"name":"company_id","type":"uuid"},{"name":"job_number","type":"text"},{"name":"name","type":"text"},{"name":"customer_id","type":"uuid"},{"name":"authorized_contract","type":"numeric"},{"name":"billed_contract","type":"numeric"},{"name":"sales_tax_billed","type":"numeric"},{"name":"retainage_held","type":"numeric"},{"name":"retainage_released","type":"numeric"},{"name":"cash_collected","type":"numeric"},{"name":"processing_fees_paid","type":"numeric"},{"name":"net_cash_collected","type":"numeric"},{"name":"outstanding_ar","type":"numeric"},{"name":"overdue_ar","type":"numeric"},{"name":"overdue_invoice_count","type":"integer"},{"name":"draft_invoice_count","type":"integer"},{"name":"open_invoice_count","type":"integer"},{"name":"unbilled_contract","type":"numeric"},{"name":"billing_percent","type":"numeric"},{"name":"collection_percent","type":"numeric"}]$shape$::jsonb then raise exception 'Unrecognized deployed project_billing_summary row shape: %',shape;end if;
 definition:=pg_get_viewdef('public.project_billing_summary'::regclass,true);execute 'create view public.carez_project_billing_prefix_bridge with(security_invoker=true) as '||definition;
 execute $ddl$create or replace view public.project_billing_summary with(security_invoker=true) as select v.*,p.contract_value::numeric(12,2) original_contract_value,coalesce((select sum(i.invoice_total) from public.invoice_financial_summary i where i.company_id=v.company_id and i.project_id=v.project_id and i.status<>'void'),0)::numeric(14,2) billed_amount,coalesce((select sum(i.amount_paid) from public.invoice_financial_summary i where i.company_id=v.company_id and i.project_id=v.project_id and i.status<>'void'),0)::numeric(14,2) collected_amount from public.carez_project_billing_prefix_bridge v join public.projects p on p.company_id=v.company_id and p.id=v.project_id$ddl$;
 revoke all on public.carez_project_billing_prefix_bridge,public.project_billing_summary from public,anon,authenticated;grant select on public.carez_project_billing_prefix_bridge,public.project_billing_summary to authenticated;
end if;
end $bridge$;
